var type = asm.GetType("Xunit.v3.ITestCaseOrderer");
if (type == null) { Console.WriteLine("Type not found"); return; }
foreach (var m in type.GetMethods()) {
    Console.Write($"{m.ReturnType.Name} {m.Name}");
    if (m.IsGenericMethod) {
        var gps = m.GetGenericArguments();
        Console.Write($"<{string.Join(",", gps.Select(g => g.Name))}>");
        foreach (var g in gps) {
            var constraints = g.GetGenericParameterConstraints();
            var attrs = g.GenericParameterAttributes;
            Console.Write($" where {g.Name}: attrs={attrs}");
            foreach (var c in constraints) Console.Write($" {c.FullName ?? c.Name}");
        }
    }
    Console.WriteLine();
}
EOF
